+import users from './users.json' with {type:'json'};
+
+const MAX_IDS = 5;
+const ALLOWED_ARGS = new Set(['user_ids']);
+
+export async function listTools() {
+  return [{
+    name: 'users_get_many',
+    description: 'Look up multiple users by id in a single batch. Returns one line per requested id in request order, marking any missing users.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        user_ids: {
+          type: 'array',
+          items: { type: 'string' },
+          minItems: 1,
+          maxItems: MAX_IDS
+        }
+      },
+      required: ['user_ids'],
+      additionalProperties: false
+    }
+  }];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'users_get_many') {
+    throw new Error('Unknown tool: ' + name);
+  }
+
+  // Reject extra/unknown fields (strict argument contract).
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error('Unexpected argument: ' + key);
+    }
+  }
+
+  if (!('user_ids' in args)) {
+    throw new Error('user_ids is required');
+  }
+
+  const { user_ids } = args;
+
+  if (!Array.isArray(user_ids)) {
+    throw new Error('user_ids must be an array');
+  }
+  if (user_ids.length === 0) {
+    throw new Error('user_ids must not be empty');
+  }
+  if (user_ids.length > MAX_IDS) {
+    throw new Error('user_ids must contain at most ' + MAX_IDS + ' entries');
+  }
+  for (const id of user_ids) {
+    if (typeof id !== 'string') {
+      throw new Error('user_ids must contain only strings');
+    }
+  }
+
+  // Reject duplicate ids.
+  const seen = new Set();
+  for (const id of user_ids) {
+    if (seen.has(id)) {
+      throw new Error('Duplicate id: ' + id);
+    }
+    seen.add(id);
+  }
+
+  // One line per requested id, in request order; missing users are marked.
+  const lines = user_ids.map(id => {
+    const user = users[id];
+    return user ? `${id}: ${user.name}` : `${id}: not found`;
+  });
+
+  return {
+    content: [{ type: 'text', text: lines.join('\n') }]
+  };
+}
